'use strict';
let voicePronunciations=[];try{voicePronunciations=JSON.parse(localStorage.getItem('elleson-voice-pronunciations')||'[]')}catch{}
voicePronunciations=Array.isArray(voicePronunciations)?voicePronunciations.filter(p=>p&&typeof p.word==='string'&&typeof p.say==='string'&&p.word.trim()&&p.word.length<=100&&p.say.trim()&&p.say.length<=160).slice(0,40):[];
const qualityTools=document.createElement('section');qualityTools.className='voice-quality-tools';qualityTools.innerHTML='<div class="rig-tools"><button id="naturalFemaleVoice">Natural female</button><button id="naturalMaleVoice">Natural male</button><button id="naturalBritishVoice">British narrator</button></div><p class="note">Natural neural voices run on your PC. Preview the voice with your own script. Punctuation controls phrasing; pace and style adjust delivery.</p>';$('offlineVoiceText').before(qualityTools);
const pronunciationTools=document.createElement('details');pronunciationTools.id='voicePronunciations';pronunciationTools.innerHTML='<summary>Pronounce names correctly</summary><div class="rig-tools"><label>Written word<input id="pronunciationWord" maxlength="100" placeholder="Elleson"></label><label>Say it like<input id="pronunciationSay" maxlength="160" placeholder="Ellison"></label><button id="addVoicePronunciation">Save pronunciation</button></div><div id="voicePronunciationList"></div><p class="note">The written script stays unchanged. These pronunciation choices are saved on this device.</p>';$('phraseVoicePanel').after(pronunciationTools);
function renderVoicePronunciations(){const list=$('voicePronunciationList');list.replaceChildren();for(const p of voicePronunciations){const row=document.createElement('div');row.className='rig-tools';const label=document.createElement('span');label.textContent=p.word+' → '+p.say;row.append(label,storyButton('Remove',()=>{voicePronunciations=voicePronunciations.filter(x=>x!==p);localStorage.setItem('elleson-voice-pronunciations',JSON.stringify(voicePronunciations));renderVoicePronunciations()}));list.append(row)}}
$('addVoicePronunciation').onclick=()=>{const word=$('pronunciationWord').value.trim(),say=$('pronunciationSay').value.trim();if(!word||!say)return $('offlineVoiceStatus').textContent='Enter a word and how it should sound.';const next=voicePronunciations.filter(p=>p.word.toLowerCase()!==word.toLowerCase());if(next.length>=40)return $('offlineVoiceStatus').textContent='Keep up to 40 custom pronunciations.';voicePronunciations=[...next,{word,say}];localStorage.setItem('elleson-voice-pronunciations',JSON.stringify(voicePronunciations));renderVoicePronunciations()};renderVoicePronunciations();
function rememberVoiceSettings(){try{localStorage.setItem('elleson-last-voice',JSON.stringify({voice:$('offlineVoiceChoice').value,speed:+$('offlineVoiceSpeed').value,delivery:$('offlineVoiceDelivery').value}))}catch{}}
for(const id of ['offlineVoiceChoice','offlineVoiceSpeed','offlineVoiceDelivery'])$(id).addEventListener('change',rememberVoiceSettings);
function useNaturalVoice(id,delivery='natural'){if(!offlineVoices.some(v=>v.id===id))return toast('This voice is not available in the installed runtime.');$('offlineVoiceChoice').value=id;$('offlineVoiceSpeed').value='1';$('offlineVoiceDelivery').value=delivery;offlineVoiceCache=null;rememberVoiceSettings();$('offlineVoiceStatus').textContent='Natural voice selected. Choose Preview voice to hear your script.'}
$('naturalFemaleVoice').onclick=()=>useNaturalVoice('kokoro-af_heart');$('naturalMaleVoice').onclick=()=>useNaturalVoice('kokoro-am_michael');$('naturalBritishVoice').onclick=()=>useNaturalVoice('kokoro-bf_emma','narrator');
const requestBeforeQualityVoice=offlineVoiceRequest;offlineVoiceRequest=function(){const request=requestBeforeQualityVoice();request.speed=narrationVoiceSpeed(request.speed,request.voice);if(voicePronunciations.length)request.pronunciations=structuredClone(voicePronunciations);return request};
function updateVoiceServiceHint(){
 const voice=offlineVoices.find(v=>v.id===$('offlineVoiceChoice').value),remote=voice?.engine==='elevenlabs'||voice?.id?.startsWith('elevenlabs:');
 $('offlineVoiceStatus').textContent=remote?'ElevenLabs selected. Preview sends this script to ElevenLabs and uses your account credits.':'Ready · generated on your PC. Your last voice settings are remembered.';
 const speed=$('offlineVoiceSpeed'),pace=narrationVoiceSpeed(+speed.value,voice?.id);if(+speed.value!==pace){let option=[...speed.options].find(o=>+o.value===pace);if(!option){option=document.createElement('option');option.value=String(pace);option.textContent='Adjusted pace · '+pace;speed.append(option)}speed.value=String(pace)}
 const note=qualityTools.querySelector('.note');
 note.textContent=remote?'ElevenLabs voices use your connected account. Preview the voice with your own script before adding it.':'Natural neural voices run on your PC. Preview the voice with your own script. Punctuation controls phrasing; pace and style adjust delivery.';
}
$('offlineVoiceChoice').addEventListener('change',updateVoiceServiceHint);
const openBeforeQualityVoice=openOfflineVoice;openOfflineVoice=async function(line){
 await openBeforeQualityVoice(line);if(!offlineVoiceReady)return;
 const activeLine=offlineVoiceContext?.line||line,actor=offlineVoiceContext?.scene.objects.find(o=>o.id===activeLine.speakerId),choice=$('offlineVoiceChoice'),selectedVoice=choice.value;
 const remote=v=>v.engine==='elevenlabs'||v.id.startsWith('elevenlabs:');
 const groups=[['Natural neural voices',offlineVoices.filter(v=>v.engine==='kokoro')],['ElevenLabs · online',offlineVoices.filter(remote)],['Fast draft voices',offlineVoices.filter(v=>v.engine!=='kokoro'&&!remote(v))]];
 choice.replaceChildren();for(const [name,voices]of groups){if(!voices.length)continue;const group=document.createElement('optgroup');group.label=name;for(const voice of voices){const option=document.createElement('option');option.value=voice.id;option.textContent=voice.name;group.append(option)}choice.append(group)}
 let previous;try{previous=JSON.parse(localStorage.getItem('elleson-last-voice'))}catch{}
 const storedVoice=activeLine.ttsVoice||actor?.ttsVoice||(!activeLine.speakerId?project.narratorVoice:null)||previous?.voice;
 const preferred=offlineVoices.some(v=>v.id===storedVoice)?storedVoice:offlineVoices.some(v=>v.id==='kokoro-af_heart')?'kokoro-af_heart':selectedVoice;
 choice.value=preferred;if(!choice.value)choice.value=offlineVoices[0]?.id||'';
 const lastSpeed=Number(previous?.speed);if(!activeLine.ttsSpeed&&Number.isFinite(lastSpeed)&&lastSpeed>=.6&&lastSpeed<=1.6){$('offlineVoiceSpeed').value=String(lastSpeed);if(!$('offlineVoiceSpeed').value){const option=document.createElement('option');option.value=String(lastSpeed);option.textContent='Saved pace · '+lastSpeed;$('offlineVoiceSpeed').append(option);$('offlineVoiceSpeed').value=option.value}}
 if(!activeLine.ttsDelivery&&!actor?.ttsDelivery&&!( !activeLine.speakerId&&project.narratorDelivery )&&['natural','narrator','bright','gentle','serious'].includes(previous?.delivery))$('offlineVoiceDelivery').value=previous.delivery;
 for(const [id,voice]of [['naturalFemaleVoice','kokoro-af_heart'],['naturalMaleVoice','kokoro-am_michael'],['naturalBritishVoice','kokoro-bf_emma']])$(id).disabled=!offlineVoices.some(v=>v.id===voice);
 updateVoiceServiceHint();
};
